def read_npz(p):
 blob=raw(p);ret={}
 with zipfile.ZipFile(io.BytesIO(blob)) as z:
  for member in z.namelist():
   data=z.read(member);assert data[:6]==b'\x93NUMPY';major=data[6];w=2 if major==1 else 4
   n=struct.unpack('<H' if major==1 else '<I',data[8:8+w])[0]
   h=ast.literal_eval(data[8+w:8+w+n].decode('latin1')); payload=data[8+w+n:]
   assert not h['fortran_order']
   dt=h['descr']; count=math.prod(h['shape'])
   if dt.startswith('<U'):
    width=int(dt[2:])*4; assert len(payload)==count*width
    values=[payload[i:i+width].decode('utf-32le').rstrip('\0') for i in range(0,len(payload),width)]
   else:
    typecode={'<f4':'f','<f8':'d','<i8':'q','<i4':'i','|b1':'b'}[dt]
    values=array(typecode);values.frombytes(payload);assert len(values)==count
   ret[member[:-4]]=dict(header=h,values=values,data_sha256=hashlib.sha256(payload).hexdigest())
